class Pesanan:
    def __init__(self, nama, jumlah_boks, harga_satuan, luar_kota, berat_kg=0):
        self.nama = nama
        self.jumlah_boks = jumlah_boks
        self.harga_satuan = harga_satuan
        self.luar_kota = luar_kota
        self.berat_kg = berat_kg

    def hitung_potongan(self):
        if self.jumlah_boks >= 150:
            return 0.15
        elif self.jumlah_boks >= 100:
            return 0.12
        elif self.jumlah_boks >= 50:
            return 0.08
        return 0.0

    def hitung_biaya_kirim(self):
        if not self.luar_kota:
            return 0
        return 10000 if self.berat_kg >= 5 else 5000

    def hitung_total(self):
        # kotor dikurangi potongan, ditambah biaya kirim
        return 0


def salin_pesanan(p):
    # kembalikan objek Pesanan baru berisi data yang sama
    return p


p1 = Pesanan("Toko Barokah Jaya", int(input()), int(input()), True, int(input()))
berat_baru = int(input())

cadangan = salin_pesanan(p1)
cadangan.berat_kg = berat_baru

print(f"Total p1: Rp{p1.hitung_total():,.0f}")
